/** 可订购组合：族 × 材质 × 表面处理 × 规格行。
 *
 * 注意 SKU 与这里的区别：**SKU 是族级的**（一个族一个号，如
 * TI-HEX-SOCKET-HEAD-CAP-SCREW），报号用的是它；这里是这个 SKU 下的
 * 具体 (规格 × 材质 × 表面) 组合 —— 询盘时说的是组合，报价单上写的是 SKU。
 */
export function skuRows(family: Family): SkuRow[] {
	const rows = DIMENSIONS[family.family_id] ?? [];
	const materials = family.materials.split('|').filter(Boolean);
	const finishes = family.finishes.split('|').filter(Boolean);
	const out: SkuRow[] = [];
	for (const r of rows) {
		for (const material of materials) {
			for (const finish of finishes) {
				out.push({
					family_id: family.family_id,
					sku: family.sku,
					material,
					finish,
					standard: r.standard,
					thread: r.thread ?? '',
					length: r.length ?? '',
					values: r,
					key: r.key,
				});
			}
		}
	}
	return out;
}

