/** 每个分类下的已发布族数量（分类页的卡片计数）。 */
export function categoryCounts(): Record<string, number> {
	const out: Record<string, number> = {};
	for (const c of CATEGORIES) {
		out[c.id] = FAMILIES.filter((f) => f.category === c.id && f.status === 'published').length;
	}
	return out;

}



